// Neighbour pairs against a brute-force reference, against ASE fixtures
// (tests/data/neighbors, generated by ASE neighbor_list("ijSdD")), and on
// the physical invariants: D = r_j - r_i + S @ cell, sortedness, half lists.

#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <limits>
#include <map>
#include <random>
#include <sstream>
#include <stdexcept>
#include <string>
#include <tuple>
