FA_TEST(boundary_report_example_excludes_pair_at_its_distance) {
    // ASE gives no pairs for cutoff = norm(p): d < cutoff is false at the
    // boundary. Both (0, 1) and (1, 0) are at distance |p|.
    const Mat3 cell = Mat3::diagonal(10.0, 10.0, 10.0);
    const Pbc pbc{{true, true, true}};
    const std::vector<double> pos{0.0, 0.0, 0.0, 1.225419616259996, 0.1358255817073355,
                                  0.14627313218150417};
    const double cutoff = 1.2415706398586912;  // numpy.linalg.norm of the second position

    FA_CHECK(run(pos, cell, pbc, cutoff).size() == 0);
    FA_CHECK(brute_force(pos, cell, pbc, cutoff).empty());

    // One ulp above the pair distance, both directions are kept.
    const double above = std::nextafter(cutoff, std::numeric_limits<double>::infinity());
    const NeighborPairs got = run(pos, cell, pbc, above);
    FA_CHECK(got.size() == 2);
    expect_same_pairs_exact(pairs_of(got), brute_force(pos, cell, pbc, above), "report example");
}

FA_TEST(random_boundary_cutoffs_match_brute_force_exactly) {
    // Cutoff set to a pair distance computed by the reference: the pair is
    // excluded at that cutoff and included one ulp above it.
    std::mt19937_64 rng(20261125);
    int tested = 0;
    for (int trial = 0; trial < 60; ++trial) {
        const Mat3 cell = random_skewed_cell(rng);
        const Pbc pbc = (trial % 4 == 0) ? Pbc{{true, true, false}} : Pbc{{true, true, true}};
        const std::vector<double> pos = random_positions(rng, 6, cell, -0.3, 1.3);
        const std::vector<Pair> near = brute_force(pos, cell, pbc, 4.0);
        if (near.empty()) {
            continue;
        }
        std::uniform_int_distribution<std::size_t> pick(0, near.size() - 1);
        const Pair chosen = near[pick(rng)];
        const double d = chosen.d;

        const std::vector<Pair> at = pairs_of(run(pos, cell, pbc, d));
        expect_same_pairs_exact(at, brute_force(pos, cell, pbc, d), "boundary at d");
        FA_CHECK(!contains_pair(at, chosen));

        const double above = std::nextafter(d, std::numeric_limits<double>::infinity());
        const std::vector<Pair> just_above = pairs_of(run(pos, cell, pbc, above));
        expect_same_pairs_exact(just_above, brute_force(pos, cell, pbc, above), "boundary above d");
        FA_CHECK(contains_pair(just_above, chosen));
        ++tested;
    }
    FA_CHECK(tested >= 40);
}

